import{_ as t}from"./chunks/function-calling-flow.DFOHK6N9.js";import{_ as a,o,c as i,aN as n}from"./chunks/framework.D31DlcCL.js";const k=JSON.parse('{"title":"Agent 进化论（三）：Skills 进化论：为什么说“函数调用”是 AI 的第一生产力？","description":"2026年了，如果你还以为 AI 只能通过文字和你交流，那你就太天真了。本文作为系列第三篇，将带你深入了解 Skills（技能）的本质——Function Calling（函数调用），看它是如何把 AI 从一个“聊天搭子”变成一个能真正操作现实世界的“超级员工”的。","frontmatter":{"title":"Agent 进化论（三）：Skills 进化论：为什么说“函数调用”是 AI 的第一生产力？","date":"2026-03-07T10:00:00.000Z","categories":["AI"],"tags":["Skills","Function Calling","API","Agent","科普"],"description":"2026年了，如果你还以为 AI 只能通过文字和你交流，那你就太天真了。本文作为系列第三篇，将带你深入了解 Skills（技能）的本质——Function Calling（函数调用），看它是如何把 AI 从一个“聊天搭子”变成一个能真正操作现实世界的“超级员工”的。","cover":"/img/agent-evolution/function-calling-flow.svg","top_img":"/img/agent-evolution/function-calling-flow.svg"},"headers":[],"relativePath":"posts/agent-evolution-3-skills.md","filePath":"posts/agent-evolution-3-skills.md","lastUpdated":null}'),e={name:"posts/agent-evolution-3-skills.md"};function s(r,l,g,h,c,d){return o(),i("div",null,[...l[0]||(l[0]=[n('<h1 id="agent-进化论-三-skills-进化论-为什么说-函数调用-是-ai-的第一生产力" tabindex="-1">Agent 进化论（三）：Skills 进化论：为什么说“函数调用”是 AI 的第一生产力？ <a class="header-anchor" href="#agent-进化论-三-skills-进化论-为什么说-函数调用-是-ai-的第一生产力" aria-label="Permalink to &quot;Agent 进化论（三）：Skills 进化论：为什么说“函数调用”是 AI 的第一生产力？&quot;">​</a></h1><h3 id="前言-别让你的-ai-助手-光说不练" tabindex="-1">前言：别让你的 AI 助手“光说不练” <a class="header-anchor" href="#前言-别让你的-ai-助手-光说不练" aria-label="Permalink to &quot;前言：别让你的 AI 助手“光说不练”&quot;">​</a></h3><p>诸位看官，且请满饮此杯。在 [上一篇](file:///Users/rs/Qsync/VSCodeProjects/MyProjects/techchangelife-rs.github.io/blog/source/_posts/agent-evolution-2-reasoning.md) 中，我们深度“解剖”了 AI 的大脑，搞清楚了它是如何进行逻辑推演的。</p><p>但问题来了：一个只有大脑、没有双手的 AI，充其量也就是个“懂球帝”——他能给你分析得头头是道，但真让他上场踢球，他连个球都碰不着。</p><p>在 Agent 的世界里，大脑负责“决策”，而 <strong>Skills（技能）</strong> 则负责“执行”。如果大脑决定了“现在需要去查一下最新的油价”，那么 Skills 就是那双去敲开石油公司 API 大门的“手”。</p><p>今天，我们要聊的就是 AI 进化史上最具生产力的一项发明：<strong>Function Calling（函数调用）</strong>。它是如何让 AI 真正从“聊天机器人”进化为“数字生产力”的？</p><hr><h2 id="第一章-什么是-skills-从-插件-到-原生能力" tabindex="-1">第一章：什么是 Skills？从“插件”到“原生能力” <a class="header-anchor" href="#第一章-什么是-skills-从-插件-到-原生能力" aria-label="Permalink to &quot;第一章：什么是 Skills？从“插件”到“原生能力”&quot;">​</a></h2><p>在 2023 年，我们曾经历过一段“插件（Plugins）”时期。那时候的 AI 想要干活，得靠各种外挂。但插件的问题是：太笨拙了，AI 经常不知道什么时候该用它。</p><p>到了 2026 年，Skills 已经成为了 Agent 的<strong>原生基因</strong>。</p><h3 id="_1-1-技能的本质-结构化的交互" tabindex="-1">1.1 技能的本质：结构化的交互 <a class="header-anchor" href="#_1-1-技能的本质-结构化的交互" aria-label="Permalink to &quot;1.1 技能的本质：结构化的交互&quot;">​</a></h3><p>一个 Skill 本质上就是一段<strong>被描述过的代码</strong>。 以前我们写程序，是人调用函数。现在，我们是把函数“展示”给 AI 听，让 AI 自己决定什么时候调用。</p><h3 id="_1-2-为什么叫-第一生产力" tabindex="-1">1.2 为什么叫“第一生产力”？ <a class="header-anchor" href="#_1-2-为什么叫-第一生产力" aria-label="Permalink to &quot;1.2 为什么叫“第一生产力”？&quot;">​</a></h3><p>如果没有 Skills，AI 只能基于它的训练数据（也就是它的记忆）来回答你。这就像一个从未出过门、只靠读旧报纸生活的人。 有了 Skills，AI 就可以：</p><ul><li><strong>访问实时数据</strong>：天气、股价、新闻。</li><li><strong>操作外部系统</strong>：发邮件、下单、改代码。</li><li><strong>执行复杂计算</strong>：通过 Python 或专门的数学库进行严谨的运算，而不是靠概率瞎猜。</li></ul><p><strong>Skills 是 AI 连接现实世界的唯一通道。</strong></p><hr><h2 id="第二章-揭秘-function-calling——ai-是如何-点火-的" tabindex="-1">第二章：揭秘 Function Calling——AI 是如何“点火”的？ <a class="header-anchor" href="#第二章-揭秘-function-calling——ai-是如何-点火-的" aria-label="Permalink to &quot;第二章：揭秘 Function Calling——AI 是如何“点火”的？&quot;">​</a></h2><p>很多同学觉得，AI 调用工具不就是写个 <code>if-else</code> 吗？ 诸位，如果是 <code>if-else</code>，那它就不是人工智能了，那是老掉牙的自动化脚本。</p><h3 id="_2-1-语义理解-从模糊意图到精准参数" tabindex="-1">2.1 语义理解：从模糊意图到精准参数 <a class="header-anchor" href="#_2-1-语义理解-从模糊意图到精准参数" aria-label="Permalink to &quot;2.1 语义理解：从模糊意图到精准参数&quot;">​</a></h3><p>Function Calling 的神奇之处在于，它能把你的<strong>模糊语言</strong>自动转化为<strong>严谨的参数</strong>。</p><blockquote><p><strong>用户说</strong>：“帮我定一张明天下午去上海的高铁票，要靠窗的。”</p></blockquote><p>大脑在处理这句话时，会经历以下过程：</p><ol><li><strong>识别目标</strong>：用户要订票，匹配 <code>book_train_ticket</code> 技能。</li><li><strong>提取参数</strong>： <ul><li><code>destination</code>: &quot;上海&quot;</li><li><code>date</code>: &quot;2026-03-08&quot;（根据“明天”自动推算）</li><li><code>preference</code>: &quot;window_seat&quot;</li></ul></li><li><strong>生成调用指令</strong>：输出一个特殊的 JSON 结构。</li></ol><h3 id="_2-2-逻辑闭环-调用、执行与反馈" tabindex="-1">2.2 逻辑闭环：调用、执行与反馈 <a class="header-anchor" href="#_2-2-逻辑闭环-调用、执行与反馈" aria-label="Permalink to &quot;2.2 逻辑闭环：调用、执行与反馈&quot;">​</a></h3><p>这就是我们在第一篇里提到的 <strong>ReAct</strong> 模式的实操版。</p><ul><li><strong>Step 1 (Thought)</strong>: 我需要订票。</li><li><strong>Step 2 (Action)</strong>: 输出 <code>book_train_ticket(to=&quot;上海&quot;, seat=&quot;靠窗&quot;)</code>。</li><li><strong>Step 3 (Observation)</strong>: 系统执行了代码，返回：“订票成功，班次为 G101。”</li><li><strong>Step 4 (Final)</strong>: 告诉用户：“票定好了，班次是 G101，祝您旅途愉快！”</li></ul><p><img src="'+t+'" alt="Function Calling 工作流"></p><hr><h2 id="第三章-json-schema——给-ai-的-使用说明书" tabindex="-1">第三章：JSON Schema——给 AI 的“使用说明书” <a class="header-anchor" href="#第三章-json-schema——给-ai-的-使用说明书" aria-label="Permalink to &quot;第三章：JSON Schema——给 AI 的“使用说明书”&quot;">​</a></h2><p>要让 AI 用好你的 Skill，你必须写一份它能读懂的“说明书”。这份说明书通常是用 <strong>JSON Schema</strong> 格式编写的。</p><h3 id="_3-1-描述-description-的力量" tabindex="-1">3.1 描述 (Description) 的力量 <a class="header-anchor" href="#_3-1-描述-description-的力量" aria-label="Permalink to &quot;3.1 描述 (Description) 的力量&quot;">​</a></h3><p>在代码里，描述可能只是个注释。但在 Agent 领域，描述就是<strong>指令</strong>。</p><ul><li>如果你的 Skill 描述是“查询天气”，AI 可能在任何时候都想用它。</li><li>如果描述是“仅在用户明确询问实时气象信息时调用的精确天气查询工具”，AI 就会变得更严谨。</li></ul><h3 id="_3-2-参数定义-给-ai-划红线" tabindex="-1">3.2 参数定义：给 AI 划红线 <a class="header-anchor" href="#_3-2-参数定义-给-ai-划红线" aria-label="Permalink to &quot;3.2 参数定义：给 AI 划红线&quot;">​</a></h3><p>你得明确告诉 AI：</p><ul><li>这个参数是必须的吗？</li><li>它的可选值有哪些？（比如：只能选“靠窗”或“过道”）</li><li>它的格式是什么？（比如：必须是 YYYY-MM-DD）</li></ul><p><strong>一份好的 JSON Schema，能减少 80% 的 Agent 调用错误。</strong></p><hr><h2 id="第四章-元编程——当-ai-开始-自我造手" tabindex="-1">第四章：元编程——当 AI 开始“自我造手” <a class="header-anchor" href="#第四章-元编程——当-ai-开始-自我造手" aria-label="Permalink to &quot;第四章：元编程——当 AI 开始“自我造手”&quot;">​</a></h2><p>这是 2026 年最硬核的领域：<strong>用 Skills 开发 Skills</strong>。</p><h3 id="_4-1-技能工厂-skill-factory" tabindex="-1">4.1 技能工厂 (Skill Factory) <a class="header-anchor" href="#_4-1-技能工厂-skill-factory" aria-label="Permalink to &quot;4.1 技能工厂 (Skill Factory)&quot;">​</a></h3><p>高级的 Agent 拥有一个特殊的技能：<code>create_new_skill</code>。 当你对 Agent 说：“我需要一个能每天帮我统计 GitHub 热门项目并自动翻译成中文的工具。” Agent 发现自己现在没这个技能，它会：</p><ol><li><strong>写代码</strong>：写一个 Python 爬虫和翻译调用脚本。</li><li><strong>封装</strong>：为这段代码写好 JSON Schema 说明书。</li><li><strong>测试</strong>：运行一下，确保能跑通。</li><li><strong>注册</strong>：把这个新技能加入到它自己的“技能包”里。</li></ol><p><strong>这意味着，Agent 的能力不再是静态的，而是随着任务的增加而自我进化。</strong></p><hr><h2 id="第五章-skills-的安全性——别让你的-agent-反水" tabindex="-1">第五章：Skills 的安全性——别让你的 Agent “反水” <a class="header-anchor" href="#第五章-skills-的安全性——别让你的-agent-反水" aria-label="Permalink to &quot;第五章：Skills 的安全性——别让你的 Agent “反水”&quot;">​</a></h2><p>给 AI 开放权限是危险的。在 2026 年，Skills 的安全治理已经成为了核心课题。</p><h3 id="_5-1-最小权限原则" tabindex="-1">5.1 最小权限原则 <a class="header-anchor" href="#_5-1-最小权限原则" aria-label="Permalink to &quot;5.1 最小权限原则&quot;">​</a></h3><p>不要给 Agent 开放 <code>rm -rf /</code> 这样的核武器。每个 Skill 应该只拥有完成特定任务所需的最小权限。</p><h3 id="_5-2-沙箱化-sandboxing" tabindex="-1">5.2 沙箱化 (Sandboxing) <a class="header-anchor" href="#_5-2-沙箱化-sandboxing" aria-label="Permalink to &quot;5.2 沙箱化 (Sandboxing)&quot;">​</a></h3><p>所有的代码执行类技能（比如 Python 解释器），都必须在完全隔离的沙箱里运行。即使 AI 写了恶意代码，它也逃不出那个小笼子。</p><h3 id="_5-3-审批流-human-in-the-loop" tabindex="-1">5.3 审批流 (Human-in-the-Loop) <a class="header-anchor" href="#_5-3-审批流-human-in-the-loop" aria-label="Permalink to &quot;5.3 审批流 (Human-in-the-Loop)&quot;">​</a></h3><p>对于关键技能（比如转账、删除数据库），必须强制加入人类确认步骤。</p><hr><h2 id="结语-skills-决定了-agent-的价值边界" tabindex="-1">结语：Skills 决定了 Agent 的价值边界 <a class="header-anchor" href="#结语-skills-决定了-agent-的价值边界" aria-label="Permalink to &quot;结语：Skills 决定了 Agent 的价值边界&quot;">​</a></h2><p>诸位看官，讲到这里，你应该已经明白：大脑决定了 Agent 的“聪明程度”，而 Skills 决定了 Agent 的**“价值上限”**。</p><p>一个没有 Skills 的 Agent 只是一个空谈家，而一个拥有丰富、安全、可进化 Skills 的 Agent，才是真正能够改变世界的“超级数字员工”。</p><p>在接下来的系列文章中，我们将进入实战环节：</p><ul><li><strong>第四篇</strong>：我们将手把手教你写一个真实的、能跑通的“天气查询”自定义 Skill，让你亲身体会 Function Calling 的魅力。</li></ul><p><strong>准备好给你的 Agent 装上第一双“手”了吗？</strong></p><p>好啦，今天的故事就到这里。欲知后事如何，且听下回分解！</p><hr><h3 id="🎁-本篇-skills-脑洞-挑战" tabindex="-1">🎁 本篇“Skills 脑洞”挑战 <a class="header-anchor" href="#🎁-本篇-skills-脑洞-挑战" aria-label="Permalink to &quot;🎁 本篇“Skills 脑洞”挑战&quot;">​</a></h3><p><strong>挑战：</strong> 如果现在要给一个“个人生活助理 Agent”开发三个核心技能，你会选择哪三个？请尝试为其中一个技能写出它的 <code>Description</code>（描述），确保 AI 能在正确的时候调用它。</p><p><strong>要求：</strong></p><ol><li>技能名称。</li><li>技能解决的具体痛点。</li><li>针对 AI 的“描述词”（100 字以内）。</li></ol><p><strong>打卡：</strong> 将你的技能设计发在评论区，让我们看看谁的 Agent 最懂生活！✨</p>',68)])])}const A=a(e,[["render",s]]);export{k as __pageData,A as default};
